using HomeLibrary;using Microsoft.AspNetCore.DataProtection;using Microsoft.Data.Sqlite;using System.Text.Json;
public static class BorrowerAccountTests {
 static void Check(bool ok,string why){if(!ok)throw new Exception("Account test: "+why);}
 static void Bad(Action action,int? status=null){try{action();throw new Exception("Expected account rejection");}catch(LibraryError e){if(status!=null)Check(e.Status==status,"expected status "+status);}}
 public static void Run(string dir,IDataProtectionProvider protection){Directory.CreateDirectory(dir);using var store=new Store(dir,protection);using var accounts=new BorrowerAccounts(dir);
  JsonElement Change(string action,object input)=>JsonSerializer.SerializeToElement(store.Apply(new(action,JsonSerializer.SerializeToElement(input,Library.Json),store.Read().Revision)),Library.Json).GetProperty("result");
  const string password="A long testing passphrase!";var registration=new AccountRegistration("reader.one",password,"Sam","sam@example.com","unused-in-model-test");var a=accounts.Register(registration);Check(a.Status=="pending"&&store.Read().State.Readers.Count==0,"registration cannot claim library records");Bad(()=>accounts.Register(registration));Bad(()=>accounts.Register(registration with{Username="new",Password="short"}));
  var token=accounts.Login(new("READER.ONE",password));Check(accounts.Resolve(token)?.Id==a.Id,"username normalization and login");Bad(()=>BorrowerAccounts.ApprovedReader(accounts.Get(a.Id),store),403);
  var b=accounts.Register(registration with{Username="reader.two",Name="Other reader",Contact="other@example.com"});
  Change("addBook",new{isbn="9780140328721",title="Matilda",author="Roald Dahl"});Change("addBorrower",new{name="Existing Sam",contact="sam@example.com"});Change("addBorrower",new{name="Other borrower",contact="other@example.com"});
  Change("checkout",new{copyId="BK-0001",borrowerId="BR-0001",checkoutDate=Library.Today});Change("returnBook",new{copyId="BK-0001"});Change("checkout",new{copyId="BK-0001",borrowerId="BR-0002",checkoutDate=Library.Today});
  var active=accounts.Approve(new(a.Id,BorrowerId:"BR-0001"),store);var reader=BorrowerAccounts.ApprovedReader(active,store);Check(active.BorrowerId=="BR-0001"&&store.Read().State.Borrowers.Count==2,"explicit approval reuses borrower");
  var view=JsonSerializer.SerializeToElement(ReadingAccess.View(store.Read(),reader,true),Library.Json);Check(view.GetProperty("loans").GetArrayLength()==1&&view.GetProperty("loans")[0].GetProperty("returnedDate").ValueKind==JsonValueKind.String,"only own borrowing history");Check(!view.ToString().Contains("other@example.com"),"another borrower's contact never projected");
  Bad(()=>accounts.Approve(new(b.Id,ReaderId:reader),store));Bad(()=>accounts.Approve(new(a.Id,BorrowerId:"BR-0002"),store));
  using(var db=new SqliteConnection("Data Source="+Path.Combine(dir,"borrower-accounts.sqlite"))){db.Open();using var q=db.CreateCommand();q.CommandText="SELECT password FROM accounts";using var rows=q.ExecuteReader();rows.Read();var first=rows.GetString(0);rows.Read();Check(first!=rows.GetString(0)&&!first.Contains(password),"salted password hashes differ");}
  for(var n=0;n<5;n++)Bad(()=>accounts.Login(new("reader.two","wrong password")),401);Bad(()=>accounts.Login(new("reader.two",password)),401);
  var reset=accounts.ResetLink(b.Id,"https://books.example").Split("#reset=")[1];accounts.Reset(new(reset,"The new testing passphrase!"));Bad(()=>accounts.Reset(new(reset,password)),401);var logged=accounts.Login(new("reader.two","The new testing passphrase!"));Check(accounts.Resolve(logged)?.Id==b.Id,"single-use recovery clears lockout");accounts.Logout(logged);Check(accounts.Resolve(logged)==null,"logout revokes session");
  var firstReset=accounts.ResetLink(a.Id,"https://books.example").Split("#reset=")[1];var finalReset=accounts.ResetLink(a.Id,"https://books.example").Split("#reset=")[1];Bad(()=>accounts.Reset(new(firstReset,password)),401);accounts.Reset(new(finalReset,"A replacement testing passphrase!"));Check(accounts.Resolve(token)==null,"password reset revokes old sessions");
  token=accounts.Login(new("reader.one","A replacement testing passphrase!"));using(var restarted=new BorrowerAccounts(dir))Check(restarted.Resolve(token)?.Id==a.Id,"credential/session persistence after restart");accounts.Block(a.Id);Check(accounts.Resolve(token)==null,"blocking revokes all sessions");Bad(()=>accounts.Login(new("reader.one","A replacement testing passphrase!")),401);
  active=accounts.Approve(new(a.Id,ReaderId:reader),store);Change("renameReader",new{readerId=reader,name="Sam changed",borrowerId="BR-0002"});Bad(()=>BorrowerAccounts.ApprovedReader(active,store),403);Bad(()=>store.AccountView(active),403);
  Check(!JsonSerializer.Serialize(accounts.List(),Library.Json).Contains("password"),"account management exposes no hashes or sessions");
  Console.WriteLine("PASS borrower registration, explicit approval, own history, password hashes, lockout, recovery, revocation and fail-closed relinking");
 }
}
